// Edit these values once. Other nodes read them from here.
// The Supabase service role key is NOT stored here: it lives in the
// "MetsXMFanZone Supabase" credential used by the Supabase HTTP nodes.
return [
  {
    json: {
      // Supabase > Project Settings > API > Project URL
      supabaseUrl: 'https://rdmrxeplasttewtlfetc.supabase.co',
      // How many days ahead to create events for.
      daysAhead: 7,
      timezone: 'America/New_York',
      // Default stream links, same as Live Stream Management uses.
      metsStreamUrl: 'https://video1.getstreamhosting.com:1936/resyweugpd/resyweugpd/playlist.m3u8',
      nyTeamStreamUrl: 'https://mystream.metsxmfanzone.com/hls/mystream.m3u8',
      // Set to false to create events as hidden drafts you publish by hand.
      publish: true,
      // Remove a team to stop creating its events.
      teams: [
        { page: 'mets', name: 'Mets', league: 'mlb', mlbTeamId: 121, hours: 3.5 },
        { page: 'ny-jets', name: 'Jets', league: 'football/nfl', espnId: 'nyj', hours: 3.5 },
        { page: 'ny-giants', name: 'Giants', league: 'football/nfl', espnId: 'nyg', hours: 3.5 },
        { page: 'ny-knicks', name: 'Knicks', league: 'basketball/nba', espnId: 'ny', hours: 2.5 },
        { page: 'brooklyn-nets', name: 'Nets', league: 'basketball/nba', espnId: 'bkn', hours: 2.5 },
        { page: 'ny-rangers', name: 'Rangers', league: 'hockey/nhl', espnId: 'nyr', hours: 3 },
        { page: 'ny-islanders', name: 'Islanders', league: 'hockey/nhl', espnId: 'nyi', hours: 3 },
      ],
    },
  },
];

// One schedule request per team. MLB for the Mets, ESPN for the rest.
const { teams, daysAhead, timezone } = $('Settings').first().json;

const ymd = (date) =>
  new Intl.DateTimeFormat('en-CA', { timeZone: timezone, year: 'numeric', month: '2-digit', day: '2-digit' }).format(date);
const start = new Date();
const end = new Date(start.getTime() + daysAhead * 24 * 60 * 60 * 1000);

return teams.map((team) => ({
  json: {
    team,
    url:
      team.league === 'mlb'
        ? `https://statsapi.mlb.com/api/v1/schedule?sportId=1&teamId=${team.mlbTeamId}&startDate=${ymd(start)}&endDate=${ymd(end)}&hydrate=team,venue`
        : `https://site.api.espn.com/apis/site/v2/sports/${team.league}/teams/${team.espnId}/schedule`,
  },
}));

// Turn every team's schedule into live_streams rows for the next few days.
const settings = $('Settings').first().json;
const requests = $('Build schedule requests').all();
const responses = $input.all();

const HOUR = 60 * 60 * 1000;
const now = Date.now();
const until = now + settings.daysAhead * 24 * HOUR;

// Same fan art the Mets schedule import uses.
const ART = 'https://rdmrxeplasttewtlfetc.supabase.co/storage/v1/object/public/content_uploads/fanart';
const METS_ART = {
  'New York Yankees': `${ART}/mets-yankees.jpg`,
  'Atlanta Braves': `${ART}/mets-braves.jpg`,
  'Philadelphia Phillies': `${ART}/mets-phillies.jpg`,
  'Los Angeles Dodgers': `${ART}/mets-dodgers.jpg`,
};

const dateLabel = (iso) =>
  new Intl.DateTimeFormat('en-US', { timeZone: settings.timezone, year: '2-digit', month: 'numeric', day: 'numeric' }).format(new Date(iso));

const games = [];

responses.forEach((response, i) => {
  const { team } = requests[i].json;
  const data = response.json;
  if (data.error) return; // This team's schedule could not be loaded; try again next run.

  if (team.league === 'mlb') {
    for (const day of data.dates ?? []) {
      for (const game of day.games ?? []) {
        const state = game.status?.detailedState ?? '';
        if (/postponed|cancelled|suspended/i.test(state) || game.status?.abstractGameState === 'Final') continue;
        const isHome = game.teams.home.team.id === team.mlbTeamId;
        const opponent = (isHome ? game.teams.away : game.teams.home).team.name;
        games.push({
          team,
          start: game.gameDate,
          isHome,
          opponent,
          venue: game.venue?.name ?? '',
          label: game.gameType === 'S' ? 'Spring Training' : game.gameType === 'R' ? 'Regular Season' : 'Postseason',
          thumbnail: METS_ART[opponent] ?? `${ART}/${isHome ? 'mets-home' : 'mets-away'}.jpg`,
        });
      }
    }
    return;
  }

  for (const event of data.events ?? []) {
    const competition = event.competitions?.[0];
    if (!competition) continue;
    const status = competition.status?.type ?? {};
    if (status.completed || /postponed|canceled|cancelled/i.test(status.name ?? '')) continue;
    const us = competition.competitors.find((c) => c.team?.abbreviation?.toLowerCase() === team.espnId)
      ?? competition.competitors.find((c) => c.team?.displayName?.includes(team.name));
    const them = competition.competitors.find((c) => c !== us);
    if (!us || !them) continue;
    games.push({
      team,
      start: new Date(event.date).toISOString(),
      isHome: us.homeAway === 'home',
      opponent: them.team.displayName,
      venue: competition.venue?.fullName ?? '',
      label: event.seasonType?.name ?? '',
      thumbnail: null,
    });
  }
});

return games
  .filter((g) => {
    const t = new Date(g.start).getTime();
    return t > now && t <= until;
  })
  .sort((a, b) => new Date(a.start) - new Date(b.start))
  .map((g) => {
    const isMets = g.team.page === 'mets';
    const where = `${g.isHome ? 'vs' : '@'} ${g.opponent}`;
    return {
      json: {
        teamPage: g.team.page,
        teamName: g.team.name,
        opponent: g.opponent,
        title: `${g.team.name} ${g.isHome ? 'Vs' : '@'} ${g.opponent} ${dateLabel(g.start)}`,
        description: [g.label, `${where}${g.venue ? ` at ${g.venue}` : ''}`].filter(Boolean).join(': '),
        stream_url: isMets ? settings.metsStreamUrl : settings.nyTeamStreamUrl,
        status: 'scheduled',
        published: settings.publish,
        scheduled_start: g.start,
        scheduled_end: new Date(new Date(g.start).getTime() + g.team.hours * HOUR).toISOString(),
        thumbnail_url: g.thumbnail,
        // Same pages the admin form sets: the team page (not for the Mets) plus "live".
        assigned_pages: isMets ? ['live'] : [g.team.page, 'live'],
      },
    };
  });

// Compare the schedule with what is already in Live Stream Management.
// New games are created. A game whose start time moved is updated, but only
// while it is still "scheduled", so a stream you already started is never touched.
const { timezone } = $('Settings').first().json;
const games = $('Build stream events').all().map((item) => item.json);
const existing = $input.all().map((item) => item.json).filter((row) => row.id);

const day = (iso) =>
  new Intl.DateTimeFormat('en-CA', { timeZone: timezone, year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date(iso));
const lower = (s) => (s ?? '').toLowerCase();

const isSameGame = (row, game) => {
  if (row.title === game.title) return true;
  if (!row.scheduled_start || day(row.scheduled_start) !== day(game.scheduled_start)) return false;
  const title = lower(row.title);
  const pages = row.assigned_pages ?? [];
  const sameTeam = game.teamPage === 'mets'
    ? /\bmets\b/.test(title)
    : pages.includes(game.teamPage) || title.includes(lower(game.teamName));
  // Match on the opponent's nickname ("Braves") so "Mets Vs Braves" and
  // "Mets Vs Atlanta Braves" count as the same game.
  const nickname = lower(game.opponent.split(' ').pop());
  return sameTeam && title.includes(nickname);
};

const out = [];
const claimed = new Set();

for (const game of games) {
  const match = existing.find((row) => !claimed.has(row.id) && isSameGame(row, game));
  const { teamPage, teamName, opponent, ...row } = game;

  if (!match) {
    out.push({ json: { action: 'create', title: game.title, row } });
    continue;
  }
  claimed.add(match.id);

  const moved = Math.abs(new Date(match.scheduled_start) - new Date(game.scheduled_start)) > 60 * 1000;
  if (moved && match.status === 'scheduled') {
    out.push({
      json: {
        action: 'update',
        id: match.id,
        title: match.title,
        row: { scheduled_start: row.scheduled_start, scheduled_end: row.scheduled_end },
      },
    });
  }
}

return out;
